# Load the grids and demos shown so far
import os, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    content = open(path).read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Keys found:", sorted(G.keys()))
print("\n" + "="*50)

# Print test input
if 'Test input' in G:
    grid = G['Test input']
    print(f"\nTest input:\n")
    for row in grid:
        print(' '.join(f'{cell:3}' for cell in row))

print("\n" + "="*50)

# Print demo pairs
for k in sorted(G.keys()):
    if k != 'Test input':
        print(f"\n{k}:\n")
        grid = G[k]
        if len(k) > 15:
            print("   " + ''.join(f'{cell:4}' for cell in grid[0]))
            for i, row in enumerate(grid[1:]):
                print(f"{i+1:2}   " + ''.join(f'{cell:4}' for cell in row))
        else:
            for row in grid:
                print(' '.join(f'{cell:4}' for cell in row))

